CREATE TABLE public.institution_resources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institution_id uuid NOT NULL REFERENCES public.institutions(id),author_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('campaign','pdf')),title text NOT NULL CHECK(length(title) BETWEEN 3 AND 140),content jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(content)='object' AND octet_length(content::text)<30000),file_path text, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','published')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.institution_resources TO authenticated; GRANT ALL ON public.institution_resources TO service_role;
ALTER TABLE public.institution_resources ENABLE ROW LEVEL SECURITY;
CREATE POLICY resource_read ON public.institution_resources FOR SELECT TO authenticated USING(public.can_edit_institution_publication(institution_id));
CREATE POLICY resource_insert ON public.institution_resources FOR INSERT TO authenticated WITH CHECK(public.can_edit_institution_publication(institution_id) AND author_id=auth.uid() AND status IN ('draft','review'));
CREATE POLICY resource_update ON public.institution_resources FOR UPDATE TO authenticated USING(public.can_edit_institution_publication(institution_id) AND (author_id=auth.uid() OR coalesce(public.institution_role_of(institution_id)='direccion',false) OR coalesce(public.has_role(auth.uid(),'admin'),false))) WITH CHECK(public.can_edit_institution_publication(institution_id));
CREATE FUNCTION public.guard_institution_resource() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF TG_OP='UPDATE' AND (NEW.institution_id<>OLD.institution_id OR NEW.author_id<>OLD.author_id) THEN RAISE EXCEPTION 'Immutable owner'; END IF;
IF NEW.kind='pdf' AND (NEW.file_path IS NULL OR NEW.file_path !~ ('^'||NEW.institution_id::text||'/[0-9a-f-]{36}\.pdf$')) THEN RAISE EXCEPTION 'Invalid PDF path'; END IF;
IF NEW.status='published' THEN
IF NOT(coalesce(public.institution_role_of(NEW.institution_id)='direccion',false) OR coalesce(public.has_role(auth.uid(),'admin'),false)) THEN RAISE EXCEPTION 'Director approval required'; END IF;
IF NEW.content->>'rights' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Publication rights and privacy review required'; END IF;
IF NEW.kind='campaign' AND NEW.content->>'observance'='true' AND (coalesce(NEW.content->>'source','') !~ '^https://[^ ]+' OR NEW.content->>'sourceConfirmed' IS DISTINCT FROM 'true') THEN RAISE EXCEPTION 'Source review required'; END IF;
END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER institution_resource_guard BEFORE INSERT OR UPDATE ON public.institution_resources FOR EACH ROW EXECUTE FUNCTION public.guard_institution_resource();
CREATE FUNCTION public.public_institution_resources() RETURNS TABLE(id uuid,institution_id uuid,institution_name text,logo_path text,kind text,title text,content jsonb,file_path text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.id,r.institution_id,i.name,i.logo_path,r.kind,r.title,r.content,r.file_path FROM public.institution_resources r JOIN public.institutions i ON i.id=r.institution_id WHERE r.status='published' ORDER BY r.updated_at DESC LIMIT 200; $$;
REVOKE ALL ON FUNCTION public.public_institution_resources() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_institution_resources() TO anon,authenticated;
CREATE POLICY editorial_file_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='institution-publications' AND (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$' AND public.can_edit_institution_publication(((storage.foldername(name))[1])::uuid));
CREATE POLICY editorial_file_staff_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='institution-publications' AND (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$' AND public.can_edit_institution_publication(((storage.foldername(name))[1])::uuid));
CREATE POLICY editorial_file_public_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='institution-publications' AND EXISTS(SELECT 1 FROM public.public_institution_resources() r WHERE r.kind='pdf' AND r.file_path=name));
CREATE TABLE public.institution_completion_counts(publication_id uuid PRIMARY KEY REFERENCES public.institution_publications(id),completions bigint NOT NULL DEFAULT 0 CHECK(completions>=0));
GRANT ALL ON public.institution_completion_counts TO service_role;
ALTER TABLE public.institution_completion_counts ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.count_institution_completion() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN; END $$;
CREATE FUNCTION public.institution_analytics() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT coalesce(public.has_role(auth.uid(),'admin'),false) THEN RAISE EXCEPTION 'Admin required'; END IF; RETURN jsonb_build_object('institutions',(SELECT count(*) FROM public.institutions WHERE NOT is_test),'practice_completions',(SELECT coalesce(sum(c.completions),0) FROM public.institution_completion_counts c JOIN public.institution_publications p ON p.id=c.publication_id JOIN public.institutions i ON i.id=p.institution_id WHERE NOT i.is_test)); END $$;
REVOKE ALL ON FUNCTION public.institution_analytics() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.institution_analytics() TO authenticated;